NIGHT_LOADED({"seed":1084,"generated_at":"2026-10-21T06:00:00Z","chain":[1,3,4,2,5],"frame":{"collector":"J.D.","intro":["Je bent de nieuwe assistent.","Op tafel ligt een briefje van de verzamelaar.","De sleutel van de voordeur zit in zijn jas, en hij is naar huis.","De klok zegt kwart over negen.","Je begint te ordenen."],"note_table":"Twaalf enveloppen invoegen.\nKast vijf blijft dicht.\nSluit af vóór twaalven.\n— J.D.","note_final":"Goed opgeborgen. Morgen om negen. — J.D.","card_desk":{"kind":"Sage","description":"In het Centraal Sagenarchief staat een leestafel met een groen kleed, en daarop een lamp met een groene kap. Langs de muur staan vijf kasten met laden vol kaarten. 's Avonds, als de anderen weg zijn, zit daar de assistent die 's avonds doorwerkte, en leest. Men ziet alleen de handen in het lamplicht.","place":"Amsterdam","prov":"N.-H.","year":1936,"code":null,"initials":"J.D.","teller":"de vorige assistent","note":"Niet lezen. Opbergen."},"trail_notes":["Niet door mij opgetekend. Mijn vorige assistent.","Zelfde hand. Hij werkte 's avonds door.","Zijn laatste. Daarna geen kaarten meer van hem.","Deze heeft hij niet opgeborgen. Ik ook niet."],"card_five":{"kind":"Sage","description":"Er was eens een nieuwe assistent op het Sagenarchief die 's avonds bleef om het opbergen af te maken. De verzamelaar was naar huis gegaan. De assistent zette vier kasten op orde en maakte toen ook de vijfde open, al was gezegd dat die dicht moest blijven. Daarna is de assistent niet meer gezien. De kaarten lagen keurig op volgorde, en wat de assistent daar zag, dat was ____.","place":"Amsterdam","prov":"N.-H.","year":"tomorrow","teller":"J.D.","initials":"J.D.","code":null},"final_words":["niets","mij","mijzelf","de assistent","de vorige assistent"],"door_locked":"Op slot. De sleutel zit in de jas van J.D.","midnight":"De klok slaat twaalf.","good_end":"Goed gedaan. Kast vijf blijft dicht.","nee":"Nee.","not_yet":"Nog niet.","into_envelope":"In de envelop.","archive_note":"Achter het schot hoef je vannacht niet.","finish_first":"Nog niet. Eerst kast {roman}.","digit_note":"{n}. Het cijfer van kast {roman}.","digit_first":"Onthouden: het slot van kast V wil er vier.","found_notes":{"chair":"Eén ligt waar ik hem gisteren neerlegde.","lamp":"Eén ligt onder de lamp. Niet de lamp verzetten.","coat":"Eén zit in mijn jas. Jas laten hangen.","typewriter":"Eén zit nog in de machine."},"floor_note":"Die hoort niet in die la.","machine_continued":"— vervolg in la 3 —","reactions":{"reopen_filed":"Die was klaar.","stalled":"Opschieten.","read_desk":"Ik had gezegd: niet lezen.","typo3":"Het staat er. Lees.","other_hand":"hij komt niet terug","five_shut":"Dicht."},"citation":"Bron: Nederlandse Volksverhalenbank, Meertens Instituut (KNAW), www.verhalenbank.nl"},"cabinets":[{"id":1,"label":"Voortekenen","digit":4,"drawers":[{"id":"1-1","type":"P2","difficulty":2.8016,"rank":0.0098,"note":"Zonder plaats. Ergens tussen de andere drie. Prik hem op de kaart.","cards":[{"id":"c1","story_id":"LINSSEN006308","role":"target","render":{"description":"Schetteren van ekster is voorloop van gevaar, huwelijk of sterfgeval.","place":null,"prov":"L.","year":1963,"code":"SINSAG 0486","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208668","original":"Wanneer men in het bos een ekster hoort slaan, dreigt er gevaar. Het kan er ook op duiden, dat er binnenkort \"een bruiloft of een lijk\" komt.","lang":"Standaardnederlands","front":"original"},"home":"1-1"},{"id":"c2","story_id":"LINSSEN002305","role":"helper","render":{"description":"Zien van drie eksters is voorteken van sterfgeval.","place":"Sint Odiliënberg","prov":"L.","year":1962,"code":"SINSAG 0486","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208317","original":"Als iemand drie eksters bij elkaar zag, dan zou iemand uit de familie sterven.","lang":"Standaardnederlands","front":"original"},"home":"1-1","geo":[51.14333,6.0]},{"id":"c3","story_id":"LINSSEN007410","role":"helper","render":{"description":"Schetteren van ekster is voorteken van een sterfgeval of een ongeluk.","place":"Leveroy","prov":"L.","year":1964,"code":"SINSAG 0486","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208799","original":"Het schateren van een ekster was een aanwijzing dat binnenkort iemand uit de familie zou sterven of dat hem een ongeluk zou overkomen.","lang":"Standaardnederlands","front":"original"},"home":"1-1","geo":[51.24917,5.84722]},{"id":"c4","story_id":"LINSSEN009208","role":"helper","render":{"description":"Aantal eksters bepaalt voorloop van geluk en ongeluk.","place":"Sint Joost","prov":"L.","year":1965,"code":"SINSAG 0486","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208963","original":"Voortekens . Wanneer drie eksters zich toonden in de nabijheid van een huis, stond er groot geluk te verwachten. Een ekster daarentegen was een voorbode van ongeluk.","lang":"Standaardnederlands","front":"original"},"home":"1-1","geo":[51.1175,5.89861]}],"hints":["Drie plaatsen staan er al. De vierde ligt daartussen.","Binnen 2 uur lopen van Sint Joost.","Zoek Heel op de kaart."],"lock":{"kind":"place","target_geo":[51.17917,5.89444],"radius_km":6.0},"on_success":{"fill_field":{"card":"c1","field":"place","value":"Heel"},"stack":["c1","c2","c3","c4"]},"found_card":null},{"id":"1-2","type":"P3","difficulty":1.2279,"rank":0.4361,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"KOOIJMAN1607","role":"intruder","render":{"description":"Weerwolven hadden kettingen om, waardoor je ze van ver kon horen aankomen. Mensen waren dan van streek.","place":"Nieuwaal","prov":"Gld.","year":1963,"code":"SINSAG 0804","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/125803","original":"Vroeger bij Sprokkelenburg onder Heukelum, daar woonde de machinist van 't stoomgemaal, die spookte daar ook. Van die verhalen dat d'r werwolve ware, diere met een ketting aan, dat je ze al van verre kon hore. De mense ware dan zo van streek.","lang":"Standaardnederlands","front":"original"},"home":"cab:3"},{"id":"c2","story_id":"CJ027402","role":"member","render":{"description":"Een vrouw hoorde eens een hoop lawaai in een aangrenzende kamer. Maar er was niets te zien. De volgende dag zakte een familielid door de vloer en kwam in de desbetreffende kamer terecht. Dat was het geluid wat de vrouw de vorige dag had gehoord.","place":"Kootstertille","prov":"Fr.","year":1967,"code":"SINSAG 0487","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/21587","original":"Ik wie op in kear by myn suster yn Twizelerheide. Wy sieten yn 't keammerke togearre by elkoar, doe hearde ik dat it der yn 'e oare keamer hiel bot oan wei gong. Myn suster fornaem it net. Ik sei: \"Hwat in lawaei.\" Wy der hinne. Mar der wie neat to sjen. Dat wy gongen wer nei 't keammerke ta to thédrinken.\nDe oare deis rekke de dochter fan myn suster troch de souder hinne boppe de keamer. De planken bijoegen har. Dat joech in stik leven. En dàt hie ik de foarige deis heard.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c3","story_id":"CJ026709","role":"member","render":{"description":"Een vrouw hoort in haar dromen vaak een stem die haar voorspellingen doet. Daarnaast hoort ze vaak het geluid van timmeren op plaatsen waar nieuwe huizen gebouwd zullen worden.","place":"Kootstertille","prov":"Fr.","year":1967,"code":"SINSAG 0487","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/21442","original":"Yn 'e droom hear ik faek in stem. Dy dielt my dan it ien of oare mei. Dêrtroch wyt ik fan alles, hwat der gebeure sil.\nIk haw trije beppesizzers, dy moesten alle trije in pop ha. Dy stem sei tsjin my: Twa derfan dat wurde jonges. Se komme allebeide Anders to hiten. (Ik wist net dat de heiten fan 'e manlju beide Anders hieten)\nTsjin 'e trêdde beppesizzer sei 'k: \"Dû krigest in famke.\" Dat is ek útkaem. It woarde tsjin my sein. Dat binne fisioenen.\nSa't ik sei, ik hear hiel faek timmerjen, sawol by dei as by nacht. En 't komt altyd nei.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c4","story_id":"CJ026702","role":"member","render":{"description":"Op een winterse namiddag hoorde een vrouw een auto op het erf, maar ze zag niets. Ook waren in de sneeuw geen sporen van een auto te vinden. Maar de volgende dag gebeurde er op de weg een ongeluk, en er kwamen allemaal mensen en auto's op het erf.","place":"Kootstertille","prov":"Fr.","year":1967,"code":"SINSAG 0487","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/21435","original":"It gebeurde in pear jier lyn. 't Wie yn 'e winter, der lei snie. 't Wie op 'e neimiddei. Ik hearde in protte lawaei op 'e wei en by ús op it hiem. Ik hearde ek in greate auto. Doe't ik op it hiem kom wie der alhiel neat to sjen. En doe't ik de oare moarns doe't it ljocht wie, nei spoaren socht yn 'e snie, wienen dy der net. Doe wist ik it oare wol. De oare deis is hjir doe in ûngelok gebeurd op 'e wei. 't Wienen allegear auto's en minsken, ek hjir op it hiem. Se ha hjir doe noch in frou yn 'e hûs brocht.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"}],"hints":["Kijk naar de nummers in rood potlood.","Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De kaart over Nieuwaal hoort bij de Weerwolven."],"lock":{"kind":"card_to_cabinet","card":"c1","cabinet":3},"on_success":{"trail_note":0,"unlock_cabinet":3,"stack":["c2","c3","c4"]}},{"id":"1-3","type":"R1","difficulty":1.1281,"rank":0.3431,"note":"De klok staat stil. Deze drie weten hoe laat het is.","cards":[{"id":"c1","story_id":"Voda_022_16","role":"omen","render":{"description":"Een geestelijke zag zijn eigen begrafenis. Vier mannen met een baar bleven de hele nacht achter hem lopen. Op dezelfde weg stierf hij later.","place":"Eindhoven","prov":"N.-Br.","year":1977,"code":"SINSAG 0481","initials":"H.E.","url":"https://www.verhalenbank.nl/items/show/129749","original":"Een geestelijke uit Oirschot zag eens zijn eigen begrafenis. Op een nacht ging hij van Oirschot naar Best. Daar hoorde hij achter zich iemand lopen. Toen ie omkeek, zag ie vier mannen die een baar droegen. Hij wilde wachten, maar toen hie stil bleef staan, bleven ook de dragers stilstaan. En als ie verder ging, gingen ook de dragers verder. Zo bleven deze vier mannen met de baar de gehele nacht achter de geestelijke lopen. Die was blij dat ie eindelijk in Best aankwam, waar hij van de schrik kon bekomen. Enige tijd later moest de geestelijke weer naar Best. Daar stierf hij plotseling. Toen droeg men het lijk van de geestelijke over dezelfde weg die hij gelopen had toen de dragers met de baar hem volgden.","lang":"Standaardnederlands","front":"description"},"home":"1-3"},{"id":"c2","story_id":"CJ099406","role":"omen","render":{"description":"Als een hond spookhuilt, gaat er binnen 4 dagen in de buurt iemand dood.","place":"Boornbergum","prov":"Fr.","year":1973,"code":"SINSAG 0486","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/36651","original":"As in houn spûkgûlde seinen se, gong der binnen fjouwer dagen ien dea yn net to fiere omtrek.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c3","story_id":"CJ065203","role":"omen","render":{"description":"Een groepje jongens schold eens een oud vrouwtje uit, van wie gezegd werd dat ze een heks was. De vrouw maakte aanstalten alsof ze over de sloot van vier meter heen zou springen, en de jongens gingen er zo snel mogelijk vandoor. Zij moest er 's nachts vaak uit om lijkstoeten te zien.","place":"Twijzelerheide","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/27375","original":"Hjir wenne yn Twizelerheide in âld minske, dat wie Minne Ael, dy gong foar in tsjoenster troch. Hja wie nachts faek warber. Hja wenne oan 'e Swâdde. Dy wie sa'n fjouwer meter breed.\nOp in kear skelden in pear jonges har út, dy wienen oan 'e oare kant fan 'e Swâdde. Doe die se in pear stappen achterút en sei: \"Ik sil jim krije\", krekt as soe se in oanloop nimme.\nDoe naeiden dy jonges hurd út.\nHja moest der nachts út as der in lykstaesje ûnderweis wie.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"}],"hints":["Lees ze nog eens. Ze tellen alle drie iets.","Drie keer hetzelfde getal. Zo laat is het.","4 uur. Zet de klok."],"lock":{"kind":"clock_hour","hour":4},"on_success":{"chime":4,"digit":{"value":4,"card":"c1"},"stack":["c1","c2","c3"]}}]},{"id":2,"label":"Witte wieven","digit":6,"drawers":[{"id":"2-1","type":"P4","difficulty":1.9078,"rank":0.9943,"note":"Doorgescheurd. De rest ligt in de doos op tafel.","cards":[{"id":"c1","story_id":"ZEEUW053","role":"top","render":{"description":"Een 's nachts van de kermis naar huis kerende boerenzoon wordt op een spookplaats aangesproken door een witte dame, die hem vraagt haar te verlossen en zo zijn fortuin te maken. Hij stemt toe en zegt telkens als de geest hem iets beveelt: \"Doe 't zelf!\" zoals de geest hem tevoren","place":"Overslag","prov":"Zl.","year":1916,"code":"SINSAG 0301","initials":"L.M.d.K.","url":"https://www.verhalenbank.nl/items/show/38979","half":"top"},"home":"2-1"},{"id":"c2","story_id":"KOOIJMAN0043","role":"distractor","render":{"description":"Mooi, maar ook angstwekkend. Ze steeg recht omhoog. Het duurde maar een paar seconden, toen was ze weer verdwenen.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c3","story_id":"DYKFRIES2187","role":"distractor","render":{"description":"Dit waren kwaadaardige geesten en spoken die mensen en kinderen ontvoerden naar hun hol. Later werden deze wezens witte juffers genoemd, maar deze waren vriendelijk en behulpzaam van aard.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c4","story_id":"CJ007910","role":"distractor","render":{"description":"De mensen durfden er 's nachts niet te komen, want ze werden er door dat witte wijf aan de kant gedreven naar het meertje toe. Zonder dat ze zelf iets deden, kwamen ze in het meertje terecht.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c5","story_id":"LYST030","role":"distractor","render":{"description":"Als tegenprestatie moet ze naakt door de kerk rennen. Ze doet dit met tegenzin. Later is er op de grond die ze heeft gekregen, een wit wief te zien. Men is ervan overtuigt dat de geest van de vrouw daar nog rondspookt.","half":"bottom","code":"SINSAG 0311"},"home":"2-1"},{"id":"c6","story_id":"CJ005402","role":"distractor","render":{"description":"In het Zwagerbosch zag hij ineens vijf vrouwen staan met puntmutsen op en lange witte rokken aan. Het was bladstil maar de pluimen van de mutsen waaiden heen en weer. Hij werd doodsbenauwd en ging naar de boerderij van de oude Bearn. Toen ze samen gingen kijken waren de vrouwen weg.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c7","story_id":"LYST007","role":"distractor","render":{"description":"Wanneer een moeder die ook een nagemaakte baby in haar wieg heeft liggen, besluit om met het kind naar de nonnen te gaan om het te leren praten, komt ze onderweg een wit wief tegen. Het witte wief vraagt aan het kind of het zich soms moet laten dopen. Opeens kan het kind praten en zegt tegen het witte wief dat het naar de nonnen gaat. De moeder weet dan dat ze een nagemaakt kind in haar handen heeft, en laat het op de grond vallen. Een boer die de kunsten van de witte wieven wel eens van dichtbij wil bekijken, slaat een van de wieven met een zware stok op de schouder. De witte wieven besluiten dan weer naar Duitsland terug te keren. Op hun reis naar Duitsland kan een van de witte wieven niet meer verder lopen. Ze wordt dan door de andere wieven levend begraven met de belofte dat ze zal wederopstaan.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c8","story_id":"VODA_044_03","role":"distractor","render":{"description":"Hij wil haar uitnodigen om met hem te dansen op het Pinksterbier. Als hij bij de Berg komt, ziet hij een witte schim: de juffer. Ze wenkt hem om stil te houden. Ze pakt Bart vast en sleept hem mee in een wervelende rondedans. Bart blijft uiteindelijk zo slap als een vaatdoekje achter. Zijn paard is naar huis gelopen en huisgenoten komen hem zoeken en brengen hem naar huis. Bart komt er echter niet meer bovenop en overlijdt binnen drie dagen.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c9","story_id":"ZEEUW049","role":"distractor","render":{"description":"Sindsdien heeft men juffrouw Jenne niet meer gezien..","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c10","story_id":"YPFOE070a","role":"distractor","render":{"description":"Een van Durk Jaringa's zonen kwam 's avonds na een feestje bij dat kruispunt langs en zag een witte gestalte vlak voor zich heen zweven. Hals over kop rende hij terug naar Jistrum. Een paar anderen hebben hem later langs het kruispunt naar huis gebracht, maar van de gestalte was niets meer te zien.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c11","story_id":"LAAN004a","role":"distractor","render":{"description":"Op de grens van Slochteren en Schildwolde wandelden ze een eikenlaan op en neer in lange, witte gewaden. Zij zijn nooit overdag gezien, maar bang waren ze niet. Ze waren in griezelige steden en op kerkhoven. Ook waren ze altijd op plaatsen waar iets gebeurd was.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c12","story_id":"ZEEUW054","role":"distractor","render":{"description":"Daar waren 3 koffers met op een 'n hond, op de 2e 'n leeuw met de sleutel van de 3e in zijn bek, die de man moet pakken. Hij durft 't niet en de vrouw neemt afscheid voor 100 jaar.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c13","story_id":"ZEEUW053","role":"bottom","render":{"description":"bevolen had. De geest neemt hem mee door gangen, deuren en zalen, tot ze komen bij 5 kisten, waarop een grote zwarte hond zit, die hem de adem in de keel doet stokken. Hij is niet meer in staat te spreken en de geest neemt voor 100 jaar afscheid en de man staat weer op de weg, waar hij werd aangesproken, en sleept zich huiswaarts en is 2 dagen later dood. Iemand hoorde van zijn avontuur, ging het ook wagen, zag om middernacht een licht voor zich uit dansen, kreeg de schrik en vluchtte weg.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"}],"hints":["Lees het bovenste stuk tot het laatste woord. Wat wordt er al genoemd?","Het bovenste stuk breekt midden in een zin af. Het onderste maakt hem af.","Het nummer is SINSAG 0301. Er zijn er drie met dat nummer in de doos."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c13"},"on_success":{"fuse":["c1","c13"],"stack":["c1","c13"]},"found_card":{"card":"c13"}},{"id":"2-2","type":"P3","difficulty":1.3535,"rank":1.0009,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"KEUNING011705","role":"intruder","render":{"description":"Witte verschijning midden op bruggetje blijft staan.","place":"Easternijtsjerk","prov":"Fr.","year":1963,"code":null,"initials":"S.K.","url":"https://www.verhalenbank.nl/items/show/131602","original":"Sa seach ien hjir ek ris sa 'n forskining midden op in planke, dy oer de sleat laei, stean. Mar dy bleau dêr stiif stean, dat de man is werom gien.","lang":"Fries","front":"original","uncatalogued":true},"home":"cab:5"},{"id":"c2","story_id":"CJ020208","role":"member","render":{"description":"Mensen zagen op een avond eens twee witte wijven.","place":"Jistrum","prov":"Fr.","year":1967,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/20586","original":"Freark en Wytske wennen op 'e Iest to Jistrum. Ik wenne yn dy tiid by de boer, 'k wie fyftsjin jier. Hja fortelden op in joun, se hienen to jounpraten west. Doe't se weromkommen en op 'e hoeke wienen, hienen dêr twa âlde wite wiven west.\nSy hienen deabinaud west en koenen foar noch achterút. In hiel skoft bleauwen se stean. Doe't se letter thús kommen wienen se noch sa forbouwerearre, dat sy koenen earst net in wurd útbringe.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c3","story_id":"CJ035001","role":"member","render":{"description":"Op een spookplaats werd vroeger vaak een witte dame op een paard gesignaleerd. Het is een spookvrouw.","place":"Harkema","prov":"Fr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/22709","original":"Op 'e Lytse Wei by de Harkema ried froeger in wite dame op in hynder, doe wie de Lytse Wei noch in sânpaed.\nDurk Pitstra hat har us njonken him hawn op in joun, doe siet er op syn eigen hynder om dat yn 't lân to bringen. Hwat hurder hy ried, hwat hurder dat frommes tasette. Hy koe har net kwyt wurde en dreau op 't lêst yn 't swit.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c4","story_id":"CJ045113","role":"member","render":{"description":"Op een spookplaats spookten vroeger witte wieven.","place":"Houtigehage","prov":"Fr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/24238","original":"Op dit ein fan 'e Folgerster loane spoeken froeger wite wiven.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"2-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over de duivel.","De kaart over Easternijtsjerk hoort bij de duivel."],"lock":{"kind":"card_to_cabinet","card":"c1","cabinet":5},"on_success":{"trail_note":3,"unlock_cabinet":5,"stack":["c2","c3","c4"]}},{"id":"2-3","type":"R2","difficulty":1.1679,"rank":1.0,"note":"Er staat iets op het raam. Niet afvegen.","cards":[{"id":"c1","story_id":"CJ015603","role":"card","render":{"description":"Een visser ziet een juffer in witte kleren en besluit haar te volgen. Het witte wief verdwijnt echter even snel als ze verschenen is.","place":"Broeksterwâld","prov":"Fr.","year":1967,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/19893","original":"Douwe syn broer Anne Feddema hie to fiskjen west. Hy hie nei 't tichtset ta west en farde de Lyts út wei werom de kant nei de brêge út. Doe kom der in juffer oan yn sniewite klean. Hy tocht: Ik wol wite hwer't dy keart, dat hy hie 't eech net fan har ôf. Doe't er oan har ta wie, died er de fêstsetter yn 'e kant en krekt doe't er dat die, wie de wite juffer fuort.","lang":"Fries (Woudfries)","front":"description"},"home":"2-3"},{"id":"c2","story_id":"WEV010904","role":"card","render":{"description":"Meid bij twee slechte mannen steekt de ene man dood en vlucht. De andere man achtervolgt haar en gooit haar, op het moment dat zij de staldeur dichtdoet, een bijl na. De bijl is als herinnering in de staldeur van een nieuwe boerderij aangebracht.","place":"Ter Borg","prov":"Gr.","year":1965,"code":"SINSAG 0161","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/43395","original":"Mien mouder vertelde mie n verhoal dat in Roswinkel gebeurd is. \n\nWazzen n moal twai heksn, dai n kind stooln. \nZe brochden dat kind noar twai keerls tou. \nDoor wur ze meid, man zai kreeg dr ook n stuk of wat kinder bie. \nTwintig joar is ze dr wol west.  De keerls leefden van roof en stelerij. \n Op n dag was de aine keerl vot. De ander mos eevn scheerd worn. \nt Wicht grip t mes en snit de kerel de haals oet. En dou dr vandeur. Man intied komp de ander in hoes en zug wat er gebeurd is. Hai grip de haksebiele en neit achter t wicht aan.  \nIn Roswinkel hef hai heur inhoald. Hai smit de biele op heur, man t is net te loat; zai was net n boerderij inloopn en har de voldeure achter zuk tou trokn. Door kwam de biele in terechte. …","lang":"Gronings","front":"description"},"home":"2-3"},{"id":"c3","story_id":"YPFOE070b","role":"card","render":{"description":"Er was eens een man die met zijn hondekar van Hardegarijp naar Bergum ging. De hele weg heeft er een witte gestalte met hem meegereisd.","place":"Burgum","prov":"Fr.","year":1973,"code":"SINSAG 0310","initials":"Y.P.","url":"https://www.verhalenbank.nl/items/show/12147","original":"Wite juffers\nDer wie ris in man, dy reizge mei de hûnekarre de Simmerdyk del fan Hurdegaryp nei Burgum. It wie jûn en tige mistich. Hy siet yn 'e hûnekarre en njonken him siet in wite gestalte. De hiele tiid is dy njonken him meireizge, oan Burgum ta. Dy man hat in benaud oerke trochmakke.","lang":"Fries","front":"description"},"home":"2-3"},{"id":"c4","story_id":"LYST075","role":"card","render":{"description":"Op een bruiloft merkt een van de gasten op dat ze zijn vergeten de witte wieve uit te nodigen. Wanneer iemand spottend de witte wieve roept, wordt er een bijl naar zijn hoofd gegooid. Hij kan net op tijd naar binnen vluchten. De deur vertoont nog altijd de tekenen van de bijl. Het witte wiefke roept dat ze hem wel te pakken had kunnen nemen, als ze haar schoentje niet was verloren.","place":"Zenderen","prov":"Ov.","year":1953,"code":"SINSAG 0161","initials":"M.S.","url":"https://www.verhalenbank.nl/items/show/13289","original":"Parallel met het verhaal van de \"spinvisite\" loopt ook 't verhaal van de \"brulfte\" (bruiloft) waar een van de gasten tegen de \"brulfteneugers\" opmerkt dat hij de \"nögste noabers\" n.l. de \"witte wieve\" heeft vergeten. De \"brulfteneuger\" laat dat niet op zich zitten, gaat naar buiten en nodigt \"de witte wieve\" uit, op spottende toon. Hij wordt onmiddelijk achterna gezeten, vlucht nog net binnenshuis, terwijl hem de bijl nagegooid wordt en 'n snee in de niendeure maakt die nog aan de kleinkinderen van het bruidspaar vertoond wordt. Hier hoort ook weer dezelfde klacht over 't schoentje bij, dat niet was vastgestrikt.","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c5","story_id":"TINNEV065","role":"sill","render":{"description":"Een man gaat met zes anderen grasstengels snijden als de eerste man ineens begint te schreeuwen. Het groepje begint te rennen. Als ze uitgerend zijn vertelt de eerste man dat hij een 'grijze juffer' had gezien.","place":"Didam","prov":"Gld.","year":1944,"code":"SINSAG 0310F","initials":"A.T.","url":"https://www.verhalenbank.nl/items/show/22411","stain":"zes"},"home":"2-3"},{"id":"c6","story_id":"YPFOE088","role":"card","render":{"description":"Een boer heeft twee zonen. De ene is 's ochtends niet van het bed te krijgen, de andere moet al het werk doen. Hij is dat op een gegeven ogenblik beu en wil zijn broer eens goed wakker maken. Daarbij raakt hij hem aan de slaap waarop deze sterft. De familie verhuist omdat ze het niet langer kunnen bolwerken. De lindeboom is blijven bloeien. De vermoorde jongen spookt nog steeds in de buurt rond.","place":"Goutum","prov":"Fr.","year":1974,"code":"SINSAG 0311","initials":"Y.P.","url":"https://www.verhalenbank.nl/items/show/12173","original":"It spoek yn 'e Foksegatten\nDe wei fan Feanwâldsterwâl nei Hurdegaryp troch de Foksegatten wie foarhinne in sânreed. Op healwei stie yn in bocht in boerespul, dêr't in famylje de Vries op wenne. Twa fan 'e soannen slepten yn it bûthûsbedsteed. Ien fan 'e jonges wie moarns min fan 't bêd te krijen en dan strûpte de oare foar 't wurk op. Dêr krige dy syn nocht fan en op in moarntiid kaam er foar 't bêd mei in tuolle yn 'e hân. Hy woe him in tikje jaan om him wekker te krijen, mar hy rekke him by ûngelok oan 'e sliep, dat er it bestoar. Syn folk wie slim oerstjoer en ferslein, foaral de broer, dy't himsels ferwiet, dat er net better oppast hie.\nDe famylje koe der net langer bankje en fûn in oar hinnekommen. De pleats waard ôfbrutsen. …","lang":"Fries","front":"description"},"home":"2-3"}],"hints":["Lees het van achteren naar voren.","Het begint met een D.","Didam. Leg die kaart op de vensterbank."],"lock":{"kind":"card_to_object","card":"c5","object":"window","text":"Didam"},"on_success":{"digit":{"value":6,"card":"c5","word":"zes","stained":"c5"},"stack":["c1","c2","c3","c4","c5","c6"]}}]},{"id":3,"label":"Weerwolven","digit":7,"drawers":[{"id":"3-1","type":"P5","difficulty":0.679,"rank":0.375,"note":"De vertellers spreken elkaar tegen. Houd de oudste aan.","cards":[{"id":"c1","story_id":"LYST274","role":"variant","render":{"description":"Knecht, die 's nachts in een wolf verandert, verdwijnt als de boer onder zijn bed een wolfshuid vindt en verbrandt.","place":"Drogteropslagen","prov":"Dr.","year":1937,"code":"SINSAG 0824","initials":"K.J.","url":"https://www.verhalenbank.nl/items/show/13538","original":"Vroeger was hier een knecht, die 's nachts in een wolf veranderde en het de mensen dan lastig maakte. Onder zijn bed vond de boer op zekere dag een wolfshuid en verbrandde die. Sedert was de knecht verdwenen.\n(Verteld door een zeventig-jarige).","lang":"Standaardnederlands","front":"description"},"home":"3-1"},{"id":"c2","story_id":"VVUNL301","role":"variant","render":{"description":"Een knecht wordt weerwolf door een leren riem, die hij verstopt. Deze wordt gevonden en in de oven verbrand; meteen komt de verdachte knecht te paard aansnellen, maar wordt tegengehoudcen en zegt als de riem verbrand is: \"Ik ben verlost!\"","place":"Echt","prov":"L.","year":1920,"code":"SINSAG 0824","initials":"F.S.S.","url":"https://www.verhalenbank.nl/items/show/35840","original":"De weerwolf \n\nOp de hoeve Bosscherhof woonde eertijds een knecht die een lederen riem bezat, welke de macht had, hem, indien hij hem omgordde, te betoveren als weerwolf. Geheimzinnig en zorgvuldig werd deze band telkenmale door de knecht verstopt en wat men ook deed, hoe men ook spiedde, men vond hem nooit. En geregeld hadden de mensen uit de omtrek, die laat huiswaarts keerden, de weerwolf te dragen. En ook iedereen herkende steeds de knecht. Men gaf elkander raad om wanneer men overvallen werd, de weerwolf op een of andere manier te prikken of te krab-ben tot hij bloed voelde of zag. Dan was men gered. …","lang":"Standaardnederlands","front":"description"},"home":"3-1"},{"id":"c3","story_id":"LINSSEN002605","role":"variant","render":{"description":"Knecht die om middernacht door velg in zwarte kat verandert, is verlost na verbranden van velg.","place":"Baexem","prov":"L.","year":1962,"code":"SINSAG 0824","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208342","original":"Volgens tweede verteller was er op Nelishof te Tungelroy een knecht die elke nacht tussen twaalf en een uur afwezig was. Door een raampje ging hij naar buiten. Hij klom dan op de schansenhoop en kwam er als kat af. De boer had hem bespied en gemerkt dat boven op de schansenhoop een velg lag van een karwiel. Die had de boer daar niet neergelegd en hij zocht verband tussen de spokerij (zwarte kat) en dat karwiel.\nDit zou hij vernietigen als de knecht afwezig was. Op zekere dag had hij hem met schapen naar Antwerpen gestuurd. Toen hij een dag weg was stak de boer zijn bakoven aan en wierp de velg erin.\nOp hetzelfde moment verscheen de knecht en wilde de oven in. Het gelukte slechts met drie man om hem daarvan te weerhouden. …","lang":"Standaardnederlands","front":"description"},"home":"3-1"},{"id":"c4","story_id":null,"role":"summary","render":{"description":"In Limburg werd een dier gezien: ____. (volgens de oudste opname)","place":null,"year":null,"code":null,"initials":"J.D.","summary":true},"home":"3-1"}],"hints":["Kijk naar de jaartallen.","De oudste is uit 1920.","Op die kaart staat een dier. Welk?"],"lock":{"kind":"word","salt":"92011994ce294905","accepted_hashes":["0dac9d66b604b69e3163a906769306df240d75810b0a9edf251977cbc74c4a33","14975d61a8b64efe08fbaa5d18658bbb282976c3a5ce4f06210d5b59c0180794","329d43f7a03d1a0afcde84adea44b34c088ac1bc4ad77120e05bfb2dc46bfa71","a335df23ddb0f79855d660f7722260ecf263eeef01b1cb1f901b664068ab9c2f","eebb3731e37585ab98881a93eb7ddbc53eea052e2810bf565f620028c74be618","fb0ac1b36832b5baf3360e8a8c93f723db295c2df2739746311ff5393394f1a6"],"fill":"c4"},"on_success":{"fill_field":{"card":"c4","field":"blank","value":"typed"},"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"3-2","type":"P3","difficulty":1.1235,"rank":0.5492,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"LINSSEN010706","role":"member","render":{"description":"Weerwolf springt op de rug, verdwijnt na bloedend verwonden.","place":"Susteren","prov":"L.","year":1966,"code":null,"initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/209104","original":"WEERWOLF. Deze viel 's avonds de mensen lastig op eenzame wegen. Hij sprong hen op de rug. Wanneer de drager evenwel een scherp voorwerp of een mes bij de hand had, en de weerwolf die de voorpoten om de nek van de drager had geslagen, bloedend kon verwonden, was van zijn last bevrijd. \nDe weerwolf nam dan de vlucht.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c2","story_id":"CJ014205","role":"intruder","render":{"description":"Op het eind van de Wâl spookt een veulen met een brijpot om zijn hals.","place":"Feanwâldsterwâl","prov":"Fr.","year":1966,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/19631","original":"Op 'e ein fan 'e Wâl oan 'e Hurdegariper kant spûke altyd in fôlle mei in brijpot om 'e hals.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:4"},{"id":"c3","story_id":"LINSSEN009004","role":"member","render":{"description":"Weerwolf laat zich dragen tot kruising van wegen.","place":"Echt","prov":"L.","year":1965,"code":null,"initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208948","original":"Weerwolf: Pustjens van Dieteren had een oom die Toon heette. Het was een stroper, die de weerwolf had gedragen van de \"Boombrug\" tot waar deze weg kruiste met een andere weg. Bij een kruising van wegen liet de weerwolf altijd los.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c4","story_id":"EGGEN005301","role":"member","render":{"description":"Gespeelde weerwolf die zich laat dragen wordt neergeslagen.","place":"Aalbeek","prov":"L.","year":1971,"code":null,"initials":"C.E.","url":"https://www.verhalenbank.nl/items/show/208115","original":"tijd : rond 1900\nplaats : aalbeek en omgeving.\n\nonderwerp: \"weerwolf\".\n\n[1.] \nin aolbik houwe ze völ te doon mèt de weerwóuf. es eine door 'ne sjtegel mòs, kaom 'r 'm 'nt dràge.\nmèh dat waor geinen echten weerwouf, dat waor eine, wat dat veur de gekkerie deeg. de wèts wie dat geit: vèl um, get kweke, en ederein zwoa bang make, tot ze neet dorsjte houwe.\ntot eine gèt dapperder waor es dae grapjas. dae houw 'ne flìnke sjtek bie zich, en dao heef 'm neer. daomèt kante ze 'm, want den anderen daag laog 'r dao.","lang":"Limburgs","front":"original","uncatalogued":true},"home":"3-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een spook.","De kaart over Feanwâldsterwâl hoort bij de Spoken."],"lock":{"kind":"card_to_cabinet","card":"c2","cabinet":4},"on_success":{"trail_note":1,"unlock_cabinet":4,"stack":["c1","c3","c4"]}},{"id":"3-3","type":"R3","difficulty":1.0236,"rank":0.3077,"note":"Als er geklopt wordt: tel. Die kaart onder de deur.","cards":[{"id":"c1","story_id":"CJ044011","role":"door","render":{"description":"Een van zeven zonen is een weerwolf. Men moet nooit ruzie krijgen met een weerwolf, want dan maakt hij je dood. \nEen meisje naaide altijd bij andere mensen. Haar vrijer vroeg haar eens om een zakdoek. Ze gaf het hem, en buiten verscheurde hij het ding helemaal. Daarna was hij weer normaal. Hij bleek een weerwolf te zijn. Toen heeft het meisje het uitgemaakt.","place":"Kollumersweach","prov":"Fr.","year":1968,"code":"SINSAG 0823","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/24049","original":"Ien fan sawn soannen wie in wjerwolf. As in wjerwolf jin kriget, makket er jin dea, seinen se froeger tsjin ús. Men mat der noait rûzje mei krije, sei in muoike yn 'e Westerein, dan pakke se jo.\nMyn wiif hat in kammeraetske hawn, dy naeide altyd by oare minsken. Dy hie forkearing mei in feint.\nOp in kear wie er by har, doe frege er har om har bûsdoek. Hja hie him de bûsdoek jown, mar doe hied er dy bûsdoek yn alle moster forskuord bûtendoar.\nLetter wie er wer goed west, mar 't is wol útrekke tusken dy beiden. Hwant hy wie in wjerwolf.\nHja hat it sels oan myn wiif forteld. Dat kammeraetske wenne oan it Wyldpaed.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"},{"id":"c2","story_id":"HOL001024","role":"card","render":{"description":"Mensen die weerwolven niet aanraken; man die aan het weerwolven is, is op twee plaatsen tegelijk; weerwolven hebben vel om.","place":"Opheusden","prov":"Gld.","year":1962,"code":null,"initials":"A.R.H.","url":"https://www.verhalenbank.nl/items/show/209732","original":"Gaart en Stoffel van Brenk konden weerwolven. Als deze en ook andere personen daarmee bezig waren, moest men ze niet “omlegge” op het bed, want dan ging het mis met hen. Mensen zagen \"Stomp\" onder de noteboom liggen, maar ook lag hij thuis op bed. Hij was toen aan het weerwolven. Weerwolven hadden een vel om.","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c3","story_id":"VVUNL049","role":"card","render":{"description":"Elke avond na het eten gaat Sjang weg en komt pas heel laat terug. Op een keer volgen ze hem en zien hem iets uit een boom halen en even later was hij een weerwolf. De pastoor wordt gehaald en Sjang moet zijn spullen tevoorschijn halen. Er kwam een schapevacht en een rood stokje met rood lint uit; die worden in de oven verbrand, terwijl drie man Sjang in bedwang houden. Als alles verkoold is, zegt hij verlost te zijn.","place":"Kessel","prov":"L.","year":1952,"code":"SINSAG 0824","initials":"J.N.","url":"https://www.verhalenbank.nl/items/show/35588","original":"De geplaagde herder \n\n't Gebeurde op 'Gravenhof' te Kessel, tussen 1860 en '70. Sjang van de Maas uit Neer was hier scheper; een onnozele, rustige kerel, die niemand kwaad deed, en elke dag zijn schapen hoedde. Maar na een tijdje maakten de boer en de boerin zich over hem ongerust. Elke avond na het eten verdween Sjang plotseling en keerde pas heel laat in de nacht weer huiswaarts. Dit werd zo verdacht dat men op een keer de knaap stilletjes achtervolgde... Men zag toen dat hij tot de holle boom liep, even voorbij het Annakapelletje; daar nam hij iets uit. Na enkele ogenblikken veranderde hij van gedaante, en stoof als schrikaanjagende weerwolf met een geweldige vaart weg. . . …","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c4","story_id":"KOOIJMAN1182","role":"card","render":{"description":"Er woonde vroeger in Blokland een vrouw en die beweerde dat ze iedere avond de weerwolf buiten tekeer hoorde gaan tussen half elf en twaalf uur.","place":"Blokland","prov":"Utr.","year":1963,"code":"SINSAG 0804","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/72678","original":"De weerwolf, de weerwolf. Nou je 't zegt. D'r woonde vroeger in Blokland een vrouw. Die woonde daar op d'r eige alleen. En die vrouw die beweerde, ze hoorde iedere avond de weerwolf buite tekeergaan. Iedere avond tusse half elf en twaalf uur. Ze sloot alles d'r voor af.","lang":"Utrechts","front":"description"},"home":"3-3"},{"id":"c5","story_id":"CJ071310","role":"card","render":{"description":"Een van acht zoons was een weerwolf. Een weerwolf kon zich nooit vol eten, hij had altijd nog honger.","place":"Houtigehage","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/28045","original":"As der acht jonges wienen, dy't op elkoar folgen yn in húshâlding, dan wie ien fan dy acht in wjerwolf. Dat wie ien dy't noait sêd koe, dy't neat fan ûnpas kom.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"}],"hints":["Wacht op het kloppen. Tel het.","Een oneven getal.","7 keer. Die kaart."],"lock":{"kind":"card_to_object","card":"c1","object":"door","n":7},"on_success":{"digit":{"value":7,"card":"c2"},"stack":["c2","c3","c4","c5"]}}]},{"id":4,"label":"Spoken","digit":3,"drawers":[{"id":"4-1","type":"P6","difficulty":3.2927,"rank":0.8527,"note":"Elk verhaal één getal. In deze volgorde.","cards":[{"id":"c1","story_id":"CJ100109","role":"clip1","render":{"description":"Een vader wilde zijn 10-jarige zoon over de vaart heentillen. Die zei opeens dat hij iets zag: een ezel of een bont paard met een man erop. De vader zag niets, maar de hond rende doodsbang naar huis. De jongen zag de verschijning toen het land inrennen, en durfde later nooit meer op die plek te komen.","place":"Kootstertille","prov":"Fr.","year":1973,"code":"SINSAG 0478","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/36744","original":"Krekt nei de lêste oarloch wienen ik en myn jonge by de Swâdde yn Twizelerheide. 't Wie sahwat by de froegere flapbrêge. Ik wie oan 'e iene kant fan 'e feart en ik soe myn jonge oerhelje. 't Is sa'n 30 jier lyn. Myn jonge is nou 40.\n\"Ik sjoch hjir hwat, heit\", sei Jan.\nJan koe net in stap mear gean. \"'t Is in ezel of in lyts bont hynderke. En dêr sit in man op\", sei er.\n\"Ik sjoch hjir neat\", sei 'k. 't Wie flakby, sei er. It hountsje dat by ús wie, wie sa deabinaud, dat it wie earder thús as wy, hoewol it oars noait by ús wei gong.\n\"Nou giet it it lân yn\", sei Jan. Midden yn 't lân waerd it wei. Jan wie sa bang, dat hy hat letter noait wer op dat plak west.","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c2","story_id":"CJ109013","role":"clip2","render":{"description":"Eén van de mannen die elkaar beloofd hebben dat de eerste van hen die sterft de ander komt vertellen hoe het in het hiernamaals is, is overleden. Op een avond verschijnt hij aan de deur bij de andere man. Als die hem vraagt hoe het daar is, antwoordt de dode dat het niet best is. De overgeblevene man wil er nooit meer over praten.","place":"De Westereen","prov":"Fr.","year":1974,"code":"SINSAG 0450","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/38352","original":"Der wie in man yn 'e Westerein, dy hie in maet, dat wie Geart. Hja gongen earlik en trou mei elkoarren om.\nHja biloofden elkoar, dat, deselde dy't der it earste fan har beiden ôf komme soe to reitsjen, dy soe oan 'e oare sizze hoe't it yn it hjirneimels wie.\nAlde Geart syn maet kom it earst to overlijden.\nOp in joun waerd der by Geart oan 'e doar kloppe.\n\"Folk! Folk!\" waerd der roppen. Geart hie in dûbelde doar, dat wie in boppedoar mei in ûnderdoar.\nDoe't Geart by de doar kaem stie dêr ien oer de ûnderdoar hinne leund en doe seach Geart dat it syn maet wie, dy't stoarn wie.\n\"Hoe is it dêr, jong?\" frege Geart.\n\"Net bêst\", sei syn maet.\nGeart woe dêr letter noait wer oer prate.","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c3","story_id":"CJ118111","role":"clip3","render":{"description":"Een stel jongens ziet twee vrouwen - een in het rood en een in het blauw - op de dijk. Even plotseling als de vrouwen verschenen zijn verdwijnen ze weer. Het zijn spoken.","place":"Garyp","prov":"Fr.","year":1979,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/31527","original":"Myn broer Wytse - dy't forstoarn is - en ik reizgen togearre nei Drylst nei in pear susters, skippersdochters, dêr't wy doe forkearing mei hienen. De moarns werom reizgen wy oer Dearsum. 't Wie dêr tusken twaën en trijen yn 'e nacht. Ik sei tsjin Wytse: \"Ik sjoch twa froulju op 'e dyk.\"\n\"Ik èk, krektlyk\", sei er.\nIk sei: \"Ien mei in reade en ien mei in blauwe jurk.\"\n\"Ik krektengelyk\", sei Wytse.\nIn skoftsje letter sei 'k: \"Ik sjoch neat mear.\"\n\"Ik ek net\", sei Wytse.\nSe wienen samar ynienen fuort. En dochs ha wy se beide klear sjoen. De reade wie hwat greater as de blauwe. Wytse en ik ha 't der letter noch faek oer hawn.","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c4","story_id":"WEV013402","role":"inside","render":{"description":"Vrouwen menen dat roggemoeders hen achtervolgen. Man op paard laat ze het paard bij de manen en de staart vasthouden waardoor ze kunnen ontkomen.","place":"Muntendam","prov":"Gr.","year":1966,"code":"SINSAG 0478","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44470","original":"n Poar vroulu binnen ook es vreselk schrokn onderweg.\nt Was al loat en mien voar gung op huus of.\nToun luipn door drei vroulu mit de appelsienekörven.\n(N.B.: In Muntendam woonden vroeger veel kooplieden; de vrouwen leurden met sinaasappels, vis en rode kool enz.).\nt Wazn Jantje Kip, Haarmke Snoef en schele Maarchie.\nInains begonnen ze haard te giern; de “rogge-mouers” zatn achter heur heer. Mien voader bleef stoan en zee: “Holt joe moar vaaste bie de moaze van t peerd; griep de steert.”\nDe vroulu greepn t peerd vaaste; de appelsienekörfkes bungelden op de rugge. Peerd klaude dr van deur en zo ontluipn ze de rogge-mouders.\n(Roggemouders moeten kleine wezens geweest zijn. …","lang":"Gronings","front":"original","note":"Deze bewaar ik apart."},"home":"4-1"}],"hints":["Elk verhaal telt.","Het eerste getal is 10.","10 — 1 — 2."],"lock":{"kind":"number3","salt":"92011994ce294905","accepted_hashes":["3f7987c95736ceb0cf452c703ca814ea40d74d61c1bbc4ef65b725ba40a22dad"]},"on_success":{"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"4-2","type":"P3","difficulty":1.3911,"rank":1.0757,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ025502","role":"member","render":{"description":"In Westereinde spoken 's nachts altijd twee meisjes.","place":"Kollum","prov":"Fr.","year":1967,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/21287","original":"Yn 'e Westerein, yn in loantsje by 't spoar, roannen yn 'e nacht altyd twa famkes om. Dy spoeken dêr. Dêr doarsten de minsken nachts net lâns.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c2","story_id":"CJ093617","role":"member","render":{"description":"Mensen zagen vroeger wel eens witte wijven.","place":"Rottevalle","prov":"Fr.","year":1972,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/33731","original":"Yn 'e omkriten fan Rottefalle hâldden froeger wite wiven ta.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c3","story_id":"CJ057303","role":"intruder","render":{"description":"Meerdere mensen hebben door het bos twee witte wijven gezien.","place":"Opende","prov":"Gr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25852","original":"Witte wiven gingen altyd door 't bos van Jild Dyk. En so ferdwenen se weer. 't Waren twee witte frouljuu.\nDit gebeurde faak. Forskeidene hebben se sien.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:2"},{"id":"c4","story_id":"CJ057209","role":"member","render":{"description":"Mensen zagen vroeger vaak een meisje in zwart zijden kleding spoken.","place":"Kollumersweach","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25831","original":"Op 'e Mûzewei (= Mûntse-wei) fan Aldwâld nei Feankleaster spoeke in juffer yn 't swart. Dy roan dêr altyd om. Underskate lju ha har dêr sjoen. Hja hie swart-sidene mofkes oan 'e hannen en in swart-sidene jurk hie se oan. Hja gong dêr nei in plaets ta. Dêr stie in plakje mei woartels flak by. Dêr roan se altyd oan ta, dan gong se werom. Guon seinen. hja gong ek wol nei 't slot ta. De minsken hearden de side ritseljen.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een witte vrouw.","De kaart over Opende hoort bij de Witte wieven."],"lock":{"kind":"card_to_cabinet","card":"c3","cabinet":2},"on_success":{"trail_note":2,"unlock_cabinet":2,"stack":["c1","c2","c4"]}},{"id":"4-3","type":"R4","difficulty":1.1867,"rank":0.6667,"note":"Als de machine begint: laten uittikken. Het vervolg zit hierin.","cards":[{"id":"c1","story_id":"CJ011305","role":"top","render":{"description":"Toen een man eens op het veld was, zweefde er een heel klein bruin hondje langs hem. 't Ging op het kanaal af.","place":"Boornbergum","prov":"Fr.","year":1966,"code":"SINSAG 0478","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/17744","half":"top"},"home":"4-3"},{"id":"c2","story_id":"CJ011305","role":"bottom","render":{"description":"De man vroeg wat het hondje wilde, maar het beestje verdween in het water. Precies drie weken later overkwam de vader van de man hetzelfde. Toen leek het hondje ook in het kanaal te verdwijnen. Het was er niet pluis.","half":"bottom","code":"SINSAG 0478","stain":"drie"},"home":"4-3"},{"id":"c3","story_id":"INZ00039","role":"half","render":{"description":"Wel hoort men de spottende stem van de berggeest dat de schat niet meer gevonden kan worden. Een meisje belooft te trouwen, en als het niet doorgaat een vat olie voor de godslamp in de kerk. Ze trouwt toch met een ander, vergeet haar belofte en sterft. Haar rusteloze ziel keert terug, maar een geestelijke weet het spook te verbannen. Nog altijd hoort men haar klagende stem: ze konden mij helpen, maar ze wilden het niet.","half":"bottom","code":"SINSAG 0410"},"home":"4-3"},{"id":"c4","story_id":"KEUNING007203","role":"half","render":{"description":"Bij benaderen wordt de spookgedaante steeds kleiner en als er naar wordt geslagen is het weg.","half":"bottom","code":"SINSAG 0478"},"home":"4-3"},{"id":"c5","story_id":"CJ060007","role":"half","render":{"description":"Op een dag gaat hij naar haar toe en tussen het kerkhof en de openbare school ziet hij haar aan de rechterkant van het pad ziten met een zwart kleed om. Hij wordt bang en keert terug naar huis. Later blijkt dat Griet die dag daar nooit is geweest.","half":"bottom","code":"SINSAG 0478"},"home":"4-3"},{"id":"c6","story_id":"KEMP328","role":"half","render":{"description":"De pastoor van de kerk komt erachter en helpt op een nacht de spookpriester met het afmaken van de mis. De priester bedankt hem hiervoor: tijdens zijn leven was hij nalatig geweest tijden de mis, daarom kon hij na zijn dood geen rust vinden, maar nu is hij verlost. De priester bidt zo hevig voor het heil van de pastoor, dat deze na een halfjaar al overlijdt.","half":"bottom","code":"SINSAG 0402"},"home":"4-3"},{"id":"c7","story_id":"CJ060905","role":"half","render":{"description":"Als Schopper, de directeur van de Wilhelminahoeve dit hoort gelooft hij het niet, maar hij moet toegeven dat ze gelijk heeft als ze het ook zelf zien.","half":"bottom","code":"SINSAG 0477"},"home":"4-3"}],"hints":["Lees wat de machine getypt heeft, tot het laatste woord.","Het vervolg noemt ‘hond’ opnieuw.","Het nummer is SINSAG 0478. Er zijn er maar drie in de envelop."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c2","object":"typewriter"},"on_success":{"fuse":["c1","c2"],"type_line":"Verteller: de vorige assistent.","digit":{"value":3,"card":"c1","word":"drie","stained":"c2"},"stack":["c1","c2","c3","c4","c5","c6","c7"]}}]},{"id":5,"label":"De duivel","digit":null,"drawers":[]}]});
